    "svg": "<svg direction=\"ltr\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 760 440\" width=\"100%\" height=\"100%\" style=\"direction: ltr; text-align: left; display: block; width: 100%; height: auto; background:#ffffff; border-radius:12px; font-family:system-ui, -apple-system, Cairo, Segoe UI, sans-serif;\">\n  <defs>\n    <linearGradient id=\"mathBg1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#faf5ff\"/>\n      <stop offset=\"100%\" stop-color=\"#f8fafc\"/>\n    </linearGradient>\n    \n  </defs>\n  <rect width=\"760\" height=\"440\" rx=\"12\" fill=\"url(#mathBg1)\"/>\n  <rect x=\"14\" y=\"14\" width=\"732\" height=\"412\" rx=\"10\" fill=\"none\" stroke=\"#d8b4fe\" stroke-width=\"1.5\"/>\n  <rect x=\"28\" y=\"24\" width=\"704\" height=\"42\" rx=\"8\" fill=\"#7e22ce\"/>\n  <text x=\"380\" y=\"51\" fill=\"#ffffff\" font-size=\"16\" font-weight=\"800\" text-anchor=\"middle\">مبرهنة فيثاغورس وعكسها (Pythagorean Theorem: c² = a² + b²)</text>\n  \n  <rect x=\"36\" y=\"80\" width=\"350\" height=\"310\" rx=\"10\" fill=\"#ffffff\" stroke=\"#e9d5ff\" stroke-width=\"1.5\"/>\n  <text x=\"211\" y=\"104\" fill=\"#581c87\" font-size=\"13\" font-weight=\"800\" text-anchor=\"middle\">مثلث قائم الزاوية (3 - 4 - 5) ومربعات أضلاعه</text>\n\n  <!-- Square on leg b (bottom: width 108) -->\n  <rect x=\"140\" y=\"268\" width=\"108\" height=\"108\" fill=\"#dbeafe\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n  <text x=\"194\" y=\"322\" fill=\"#1e40af\" font-size=\"13\" font-weight=\"800\" text-anchor=\"middle\">b² = 4² = 16</text>\n\n  <!-- Square on leg a (left: height 81) -->\n  <rect x=\"59\" y=\"187\" width=\"81\" height=\"81\" fill=\"#dcfce7\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n  <text x=\"99\" y=\"232\" fill=\"#166534\" font-size=\"12\" font-weight=\"800\" text-anchor=\"middle\">a² = 3² = 9</text>\n\n  <!-- Square on hypotenuse c (rotated polygon from (140,187) to (248,268)) -->\n  <!-- vec = (108, 81), perp_out = (81, -108) -->\n  <polygon points=\"140,187 248,268 329,160 221,79\" fill=\"#f3e8ff\" stroke=\"#7e22ce\" stroke-width=\"2\"/>\n  <text x=\"235\" y=\"168\" fill=\"#581c87\" font-size=\"13\" font-weight=\"900\" text-anchor=\"middle\">c² = 5² = 25</text>\n  <text x=\"235\" y=\"186\" fill=\"#6b21a8\" font-size=\"11\" font-weight=\"700\" text-anchor=\"middle\">(9 + 16 = 25)</text>\n\n  <!-- Right Triangle -->\n  <polygon points=\"140,187 140,268 248,268\" fill=\"#fef3c7\" stroke=\"#0f172a\" stroke-width=\"2.5\"/>\n  <rect x=\"140\" y=\"254\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n  <text x=\"128\" y=\"232\" fill=\"#15803d\" font-size=\"12\" font-weight=\"800\" text-anchor=\"end\">a = 3</text>\n  <text x=\"194\" y=\"284\" fill=\"#1d4ed8\" font-size=\"12\" font-weight=\"800\" text-anchor=\"middle\">b = 4</text>\n  <text x=\"206\" y=\"218\" fill=\"#7e22ce\" font-size=\"12\" font-weight=\"900\" text-anchor=\"start\">c = 5 (الوتر)</text>\n\n  <!-- Right Panel: Formula & Converse -->\n  <g transform=\"translate(402, 80)\">\n    <rect width=\"322\" height=\"145\" rx=\"10\" fill=\"#ffffff\" stroke=\"#d8b4fe\" stroke-width=\"1.5\"/>\n    <rect width=\"322\" height=\"32\" rx=\"10\" fill=\"#f3e8ff\"/>\n    <text x=\"161\" y=\"21\" fill=\"#581c87\" font-size=\"13\" font-weight=\"800\" text-anchor=\"middle\">1. نص نظرية فيثاغورس</text>\n    <text x=\"306\" y=\"56\" fill=\"#334155\" font-size=\"11.5\" font-weight=\"700\" text-anchor=\"end\">مربع طول الوتر يساوي مجموع مربعي الضلعين القائمين:</text>\n    <rect x=\"46\" y=\"68\" width=\"230\" height=\"34\" rx=\"6\" fill=\"#faf5ff\" stroke=\"#a855f7\"/>\n    <text x=\"161\" y=\"90\" fill=\"#6b21a8\" font-size=\"15\" font-weight=\"900\" text-anchor=\"middle\">c² = a² + b²  ⇒  c = √(a² + b²)</text>\n    <text x=\"306\" y=\"126\" fill=\"#475569\" font-size=\"11\" font-weight=\"700\" text-anchor=\"end\">لإيجاد ضلع قائم: a = √(c² - b²)</text>\n  </g>\n\n  <g transform=\"translate(402, 240)\">\n    <rect width=\"322\" height=\"150\" rx=\"10\" fill=\"#ffffff\" stroke=\"#86efac\" stroke-width=\"1.5\"/>\n    <rect width=\"322\" height=\"32\" rx=\"10\" fill=\"#dcfce7\"/>\n    <text x=\"161\" y=\"21\" fill=\"#166534\" font-size=\"13\" font-weight=\"800\" text-anchor=\"middle\">2. عكس نظرية فيثاغورس (اختبار القائمة)</text>\n    <text x=\"306\" y=\"56\" fill=\"#334155\" font-size=\"11.5\" font-weight=\"700\" text-anchor=\"end\">إذا كان مربع أطول ضلع يساوي مجموع مربعي الآخرين:</text>\n    <text x=\"161\" y=\"82\" fill=\"#15803d\" font-size=\"13\" font-weight=\"900\" text-anchor=\"middle\">c² = a² + b²  ⇒  المثلث قائم الزاوية ✓</text>\n    <text x=\"161\" y=\"106\" fill=\"#b91c1c\" font-size=\"12\" font-weight=\"800\" text-anchor=\"middle\">c² ≠ a² + b²  ⇒  المثلث غير قائم الزاوية ✗</text>\n    <text x=\"306\" y=\"132\" fill=\"#475569\" font-size=\"11\" font-weight=\"700\" text-anchor=\"end\">مثال شهير: (6, 8, 10) و (5, 12, 13) و (8, 15, 17)</text>\n  </g>\n\n  <text x=\"726\" y=\"414\" fill=\"#64748b\" font-size=\"11\" font-weight=\"700\" text-anchor=\"end\">إعداد المهندس أسامة خليل هاشم</text>\n  <text x=\"34\" y=\"414\" fill=\"#7e22ce\" font-size=\"11\" font-weight=\"700\" text-anchor=\"start\">النظام التعليمي التفاعلي الشامل • الرياضيات</text>\n</svg>"
