    "svg": "<svg direction=\"ltr\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 760 440\" width=\"100%\" height=\"100%\" style=\"direction: ltr; text-align: left; display: block; width: 100%; height: auto; background:#ffffff; border-radius:12px; font-family:system-ui, -apple-system, Cairo, Segoe UI, sans-serif;\">\n  <defs>\n    <linearGradient id=\"mathBg8\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#faf5ff\"/>\n      <stop offset=\"100%\" stop-color=\"#f8fafc\"/>\n    </linearGradient>\n    <radialGradient id=\"mathSphere8\" cx=\"35%\" cy=\"35%\" r=\"65%\"><stop offset=\"0%\" stop-color=\"#ffffff\"/><stop offset=\"60%\" stop-color=\"#bae6fd\"/><stop offset=\"100%\" stop-color=\"#38bdf8\"/></radialGradient>\n  </defs>\n  <rect width=\"760\" height=\"440\" rx=\"12\" fill=\"url(#mathBg8)\"/>\n  <rect x=\"14\" y=\"14\" width=\"732\" height=\"412\" rx=\"10\" fill=\"none\" stroke=\"#d8b4fe\" stroke-width=\"1.5\"/>\n  <rect x=\"28\" y=\"24\" width=\"704\" height=\"42\" rx=\"8\" fill=\"#7e22ce\"/>\n  <text x=\"380\" y=\"51\" fill=\"#ffffff\" font-size=\"16\" font-weight=\"800\" text-anchor=\"middle\">الأسطوانة الدائرية القائمة والكرة (الخصائص، المساحة السطحية، والحجم)</text>\n  \n  <!-- Left: Cylinder -->\n  <g transform=\"translate(34, 82)\">\n    <rect width=\"336\" height=\"306\" rx=\"10\" fill=\"#ffffff\" stroke=\"#a855f7\" stroke-width=\"1.8\"/>\n    <rect width=\"336\" height=\"34\" rx=\"10\" fill=\"#f3e8ff\"/>\n    <text x=\"168\" y=\"22\" fill=\"#581c87\" font-size=\"13\" font-weight=\"900\" text-anchor=\"middle\">1. الأسطوانة الدائرية القائمة (Cylinder)</text>\n\n    <!-- Cylinder 3D -->\n    <ellipse cx=\"168\" cy=\"84\" rx=\"68\" ry=\"18\" fill=\"#e9d5ff\" stroke=\"#7e22ce\" stroke-width=\"2.2\"/>\n    <line x1=\"100\" y1=\"84\" x2=\"100\" y2=\"178\" stroke=\"#7e22ce\" stroke-width=\"2.2\"/>\n    <line x1=\"236\" y1=\"84\" x2=\"236\" y2=\"178\" stroke=\"#7e22ce\" stroke-width=\"2.2\"/>\n    <path d=\"M 100,178 A 68,18 0 0,0 236,178\" fill=\"#faf5ff\" stroke=\"#7e22ce\" stroke-width=\"2.2\"/>\n    <path d=\"M 100,178 A 68,18 0 0,1 236,178\" fill=\"none\" stroke=\"#7e22ce\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/>\n    <!-- Radius & Height -->\n    <line x1=\"168\" y1=\"84\" x2=\"236\" y2=\"84\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n    <text x=\"202\" y=\"79\" fill=\"#dc2626\" font-size=\"11.5\" font-weight=\"900\" text-anchor=\"middle\">r</text>\n    <line x1=\"168\" y1=\"84\" x2=\"168\" y2=\"178\" stroke=\"#0284c7\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/>\n    <text x=\"158\" y=\"136\" fill=\"#0284c7\" font-size=\"12\" font-weight=\"900\" text-anchor=\"end\">h</text>\n\n    <rect x=\"18\" y=\"206\" width=\"300\" height=\"86\" rx=\"8\" fill=\"#faf5ff\" stroke=\"#d8b4fe\"/>\n    <text x=\"304\" y=\"226\" fill=\"#581c87\" font-size=\"11.5\" font-weight=\"800\" text-anchor=\"end\">• الحجم: V = π r² h</text>\n    <text x=\"304\" y=\"248\" fill=\"#6b21a8\" font-size=\"11.5\" font-weight=\"800\" text-anchor=\"end\">• المساحة الجانبية: L.A = 2 π r h</text>\n    <text x=\"304\" y=\"270\" fill=\"#1e293b\" font-size=\"11.5\" font-weight=\"800\" text-anchor=\"end\">• المساحة الكلية: T.A = 2 π r h + 2 π r²</text>\n  </g>\n\n  <!-- Right: Sphere -->\n  <g transform=\"translate(390, 82)\">\n    <rect width=\"336\" height=\"306\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"1.8\"/>\n    <rect width=\"336\" height=\"34\" rx=\"10\" fill=\"#e0f2fe\"/>\n    <text x=\"168\" y=\"22\" fill=\"#0369a1\" font-size=\"13\" font-weight=\"900\" text-anchor=\"middle\">2. الكرة (Sphere)</text>\n\n    <circle cx=\"168\" cy=\"128\" r=\"64\" fill=\"url(#mathSphere8)\" stroke=\"#0284c7\" stroke-width=\"2.2\"/>\n    <ellipse cx=\"168\" cy=\"128\" rx=\"64\" ry=\"18\" fill=\"none\" stroke=\"#0369a1\" stroke-width=\"1.6\" stroke-dasharray=\"5 4\"/>\n    <circle cx=\"168\" cy=\"128\" r=\"3.5\" fill=\"#dc2626\"/>\n    <line x1=\"168\" y1=\"128\" x2=\"232\" y2=\"128\" stroke=\"#dc2626\" stroke-width=\"2.2\"/>\n    <text x=\"200\" y=\"120\" fill=\"#dc2626\" font-size=\"12\" font-weight=\"900\" text-anchor=\"middle\">r</text>\n\n    <rect x=\"18\" y=\"206\" width=\"300\" height=\"86\" rx=\"8\" fill=\"#f0f9ff\" stroke=\"#7dd3fc\"/>\n    <text x=\"304\" y=\"228\" fill=\"#0369a1\" font-size=\"12\" font-weight=\"900\" text-anchor=\"end\">• الحجم: V = (4/3) π r³</text>\n    <text x=\"304\" y=\"252\" fill=\"#0284c7\" font-size=\"12\" font-weight=\"900\" text-anchor=\"end\">• المساحة السطحية: S.A = 4 π r²</text>\n    <text x=\"304\" y=\"276\" fill=\"#475569\" font-size=\"10.8\" font-weight=\"700\" text-anchor=\"end\">• كل نقطة على سطحها تبعد البعد نفسه r عن المركز</text>\n  </g>\n\n  <text x=\"726\" y=\"414\" fill=\"#64748b\" font-size=\"11\" font-weight=\"700\" text-anchor=\"end\">إعداد المهندس أسامة خليل هاشم</text>\n  <text x=\"34\" y=\"414\" fill=\"#7e22ce\" font-size=\"11\" font-weight=\"700\" text-anchor=\"start\">النظام التعليمي التفاعلي الشامل • الرياضيات</text>\n</svg>"
