    "svg": "<svg direction=\"ltr\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 760 440\" width=\"100%\" height=\"100%\" style=\"direction: ltr; text-align: left; display: block; width: 100%; height: auto; background:#ffffff; border-radius:12px; font-family:system-ui, -apple-system, Cairo, Segoe UI, sans-serif;\">\n  <defs>\n    <linearGradient id=\"mathBg17\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#faf5ff\"/>\n      <stop offset=\"100%\" stop-color=\"#f8fafc\"/>\n    </linearGradient>\n    <linearGradient id=\"mathProbGrad17\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\"><stop offset=\"0%\" stop-color=\"#ef4444\"/><stop offset=\"50%\" stop-color=\"#f59e0b\"/><stop offset=\"100%\" stop-color=\"#22c55e\"/></linearGradient>\n  </defs>\n  <rect width=\"760\" height=\"440\" rx=\"12\" fill=\"url(#mathBg17)\"/>\n  <rect x=\"14\" y=\"14\" width=\"732\" height=\"412\" rx=\"10\" fill=\"none\" stroke=\"#d8b4fe\" stroke-width=\"1.5\"/>\n  <rect x=\"28\" y=\"24\" width=\"704\" height=\"42\" rx=\"8\" fill=\"#7e22ce\"/>\n  <text x=\"380\" y=\"51\" fill=\"#ffffff\" font-size=\"16\" font-weight=\"800\" text-anchor=\"middle\">فضاء العينة (الرسم الشجري) ومقياس الاحتمال النظري والتجريبي</text>\n  \n  <!-- Left: Tree Diagram (Coin x 3 colors or Coin x Die sample) -->\n  <g transform=\"translate(34, 82)\">\n    <rect width=\"346\" height=\"306\" rx=\"10\" fill=\"#ffffff\" stroke=\"#d8b4fe\" stroke-width=\"1.6\"/>\n    <rect width=\"346\" height=\"32\" rx=\"10\" fill=\"#f3e8ff\"/>\n    <text x=\"173\" y=\"21\" fill=\"#581c87\" font-size=\"12.5\" font-weight=\"900\" text-anchor=\"middle\">الرسم الشجري: قطعتا نقود (2 × 2 = 4 نواتج)</text>\n\n    <!-- Root -->\n    <circle cx=\"52\" cy=\"146\" r=\"20\" fill=\"#7e22ce\"/>\n    <text x=\"52\" y=\"151\" fill=\"#ffffff\" font-size=\"11\" font-weight=\"900\" text-anchor=\"middle\">البداية</text>\n\n    <!-- Branches 1 -->\n    <line x1=\"72\" y1=\"146\" x2=\"132\" y2=\"92\" stroke=\"#7e22ce\" stroke-width=\"2.4\"/>\n    <line x1=\"72\" y1=\"146\" x2=\"132\" y2=\"200\" stroke=\"#0284c7\" stroke-width=\"2.4\"/>\n\n    <rect x=\"132\" y=\"74\" width=\"52\" height=\"34\" rx=\"6\" fill=\"#faf5ff\" stroke=\"#7e22ce\" stroke-width=\"1.8\"/>\n    <text x=\"158\" y=\"96\" fill=\"#581c87\" font-size=\"12\" font-weight=\"900\" text-anchor=\"middle\">صورة H</text>\n\n    <rect x=\"132\" y=\"182\" width=\"52\" height=\"34\" rx=\"6\" fill=\"#f0f9ff\" stroke=\"#0284c7\" stroke-width=\"1.8\"/>\n    <text x=\"158\" y=\"204\" fill=\"#0369a1\" font-size=\"12\" font-weight=\"900\" text-anchor=\"middle\">كتابة T</text>\n\n    <!-- Branches 2 -->\n    <line x1=\"184\" y1=\"91\" x2=\"236\" y2=\"66\" stroke=\"#7e22ce\" stroke-width=\"2\"/>\n    <line x1=\"184\" y1=\"91\" x2=\"236\" y2=\"116\" stroke=\"#7e22ce\" stroke-width=\"2\"/>\n    <line x1=\"184\" y1=\"199\" x2=\"236\" y2=\"174\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n    <line x1=\"184\" y1=\"199\" x2=\"236\" y2=\"224\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n\n    <rect x=\"236\" y=\"52\" width=\"90\" height=\"26\" rx=\"5\" fill=\"#dcfce7\" stroke=\"#16a34a\"/>\n    <text x=\"281\" y=\"69\" fill=\"#15803d\" font-size=\"11\" font-weight=\"900\" text-anchor=\"middle\">H → (H, H)</text>\n    <rect x=\"236\" y=\"102\" width=\"90\" height=\"26\" rx=\"5\" fill=\"#f3e8ff\" stroke=\"#a855f7\"/>\n    <text x=\"281\" y=\"119\" fill=\"#581c87\" font-size=\"11\" font-weight=\"900\" text-anchor=\"middle\">T → (H, T)</text>\n    <rect x=\"236\" y=\"160\" width=\"90\" height=\"26\" rx=\"5\" fill=\"#f3e8ff\" stroke=\"#a855f7\"/>\n    <text x=\"281\" y=\"177\" fill=\"#581c87\" font-size=\"11\" font-weight=\"900\" text-anchor=\"middle\">H → (T, H)</text>\n    <rect x=\"236\" y=\"210\" width=\"90\" height=\"26\" rx=\"5\" fill=\"#fee2e2\" stroke=\"#ef4444\"/>\n    <text x=\"281\" y=\"227\" fill=\"#b91c1c\" font-size=\"11\" font-weight=\"900\" text-anchor=\"middle\">T → (T, T)</text>\n\n    <rect x=\"18\" y=\"252\" width=\"310\" height=\"38\" rx=\"6\" fill=\"#faf5ff\" stroke=\"#d8b4fe\"/>\n    <text x=\"173\" y=\"275\" fill=\"#581c87\" font-size=\"11.5\" font-weight=\"900\" text-anchor=\"middle\">مبدأ العد الأساسي: عدد النواتج الكلي = m × n</text>\n  </g>\n\n  <!-- Right: Probability Scale & Formulas -->\n  <g transform=\"translate(396, 82)\">\n    <rect width=\"330\" height=\"306\" rx=\"10\" fill=\"#ffffff\" stroke=\"#d8b4fe\" stroke-width=\"1.6\"/>\n    <rect width=\"330\" height=\"32\" rx=\"10\" fill=\"#7e22ce\"/>\n    <text x=\"165\" y=\"21\" fill=\"#ffffff\" font-size=\"12.5\" font-weight=\"900\" text-anchor=\"middle\">مقياس الاحتمال وقوانينه (0 ≤ P(E) ≤ 1)</text>\n\n    <!-- Gradient Scale Bar -->\n    <rect x=\"25\" y=\"64\" width=\"280\" height=\"16\" rx=\"8\" fill=\"url(#mathProbGrad17)\"/>\n    <circle cx=\"25\" cy=\"72\" r=\"6\" fill=\"#dc2626\"/>\n    <circle cx=\"165\" cy=\"72\" r=\"6\" fill=\"#d97706\"/>\n    <circle cx=\"305\" cy=\"72\" r=\"6\" fill=\"#16a34a\"/>\n    <text x=\"25\" y=\"100\" fill=\"#b91c1c\" font-size=\"10.5\" font-weight=\"900\" text-anchor=\"middle\">0 (مستحيل)</text>\n    <text x=\"165\" y=\"100\" fill=\"#b45309\" font-size=\"10.5\" font-weight=\"900\" text-anchor=\"middle\">½ = 50% (متساوٍ)</text>\n    <text x=\"305\" y=\"100\" fill=\"#15803d\" font-size=\"10.5\" font-weight=\"900\" text-anchor=\"middle\">1 (مؤكد)</text>\n\n    <rect x=\"16\" y=\"118\" width=\"298\" height=\"58\" rx=\"8\" fill=\"#faf5ff\" stroke=\"#d8b4fe\"/>\n    <text x=\"302\" y=\"138\" fill=\"#581c87\" font-size=\"11.5\" font-weight=\"900\" text-anchor=\"end\">1. الاحتمال النظري (P(E) = m / n):</text>\n    <text x=\"302\" y=\"160\" fill=\"#334155\" font-size=\"11\" font-weight=\"700\" text-anchor=\"end\">m = عدد عناصر الحدث ، n = عدد عناصر فضاء العينة S</text>\n\n    <rect x=\"16\" y=\"186\" width=\"298\" height=\"52\" rx=\"8\" fill=\"#eff6ff\" stroke=\"#93c5fd\"/>\n    <text x=\"302\" y=\"206\" fill=\"#1d4ed8\" font-size=\"11.5\" font-weight=\"900\" text-anchor=\"end\">2. الاحتمال التجريبي:</text>\n    <text x=\"302\" y=\"226\" fill=\"#334155\" font-size=\"11\" font-weight=\"700\" text-anchor=\"end\">= (عدد مرات تحقق الحدث فعلياً) ÷ (العدد الكلي للتجارب)</text>\n\n    <rect x=\"16\" y=\"246\" width=\"298\" height=\"46\" rx=\"8\" fill=\"#f0fdf4\" stroke=\"#86efac\"/>\n    <text x=\"165\" y=\"274\" fill=\"#15803d\" font-size=\"11.5\" font-weight=\"900\" text-anchor=\"middle\">الحدث المتمم: P(E') = 1 - P(E)</text>\n  </g>\n\n  <text x=\"726\" y=\"414\" fill=\"#64748b\" font-size=\"11\" font-weight=\"700\" text-anchor=\"end\">إعداد المهندس أسامة خليل هاشم</text>\n  <text x=\"34\" y=\"414\" fill=\"#7e22ce\" font-size=\"11\" font-weight=\"700\" text-anchor=\"start\">النظام التعليمي التفاعلي الشامل • الرياضيات</text>\n</svg>"
