window.getMathDiagram = function(lessonId) {
  if (!window.MATH_DIAGRAMS) return null;
  const id = Number(lessonId);
  return window.MATH_DIAGRAMS.find(function(d) {
    return d.lessonId === id || (Array.isArray(d.lessonIds) && d.lessonIds.includes(id));
  }) || null;
};

window.getMathDiagramsForLesson = function(lessonId) {
  if (!window.MATH_DIAGRAMS) return [];
  const id = Number(lessonId);
  return window.MATH_DIAGRAMS.filter(function(d) {
    return d.lessonId === id || (Array.isArray(d.lessonIds) && d.lessonIds.includes(id));
  });
};
